import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

conv_transpose3d_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void conv_transpose3d_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    const int N,
    const int C_in,
    const int D_in,
    const int H_in,
    const int W_in,
    const int C_out,
    const int D_out,
    const int H_out,
    const int W_out,
    const int kD,
    const int kH,
    const int kW,
    const int stride_d,
    const int stride_h,
    const int stride_w,
    const int pad_d,
    const int pad_h,
    const int pad_w,
    const int groups,
    const int C_in_per_group,
    const int C_out_per_group,
    const bool has_bias
) {
    const long total = (long)N * C_out * D_out * H_out * W_out;
    long idx = blockIdx.x * (long)blockDim.x + threadIdx.x;
    long stride_step = (long)gridDim.x * blockDim.x;

    for (; idx < total; idx += stride_step) {
        long tmp = idx;
        const int ow = tmp % W_out; tmp /= W_out;
        const int oh = tmp % H_out; tmp /= H_out;
        const int od = tmp % D_out; tmp /= D_out;
        const int oc = tmp % C_out; tmp /= C_out;
        const int n  = tmp;

        const int group_id = oc / C_out_per_group;
        const int oc_in_group = oc % C_out_per_group;
        const int ic_start = group_id * C_in_per_group;

        float acc = 0.0f;

        for (int kd = 0; kd < kD; kd++) {
            int id_nom = od + pad_d - kd;
            if (id_nom < 0) continue;
            if (id_nom % stride_d != 0) continue;
            int id = id_nom / stride_d;
            if (id < 0 || id >= D_in) continue;

            for (int kh = 0; kh < kH; kh++) {
                int ih_nom = oh + pad_h - kh;
                if (ih_nom < 0) continue;
                if (ih_nom % stride_h != 0) continue;
                int ih = ih_nom / stride_h;
                if (ih < 0 || ih >= H_in) continue;

                for (int kw = 0; kw < kW; kw++) {
                    int iw_nom = ow + pad_w - kw;
                    if (iw_nom < 0) continue;
                    if (iw_nom % stride_w != 0) continue;
                    int iw = iw_nom / stride_w;
                    if (iw < 0 || iw >= W_in) continue;

                    for (int icg = 0; icg < C_in_per_group; icg++) {
                        int ic = ic_start + icg;

                        long input_idx = (((long)n * C_in + ic) * D_in + id) * H_in * W_in
                                          + (long)ih * W_in + iw;

                        long weight_idx = (((long)ic * C_out_per_group + oc_in_group) * kD + kd) * kH * kW
                                           + (long)kh * kW + kw;

                        acc += input[input_idx] * weight[weight_idx];
                    }
                }
            }
        }

        if (has_bias) {
            acc += bias[oc];
        }

        long out_idx = (((long)n * C_out + oc) * D_out + od) * H_out * W_out
                        + (long)oh * W_out + ow;
        output[out_idx] = acc;
    }
}

torch::Tensor conv_transpose3d_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride_d, int stride_h, int stride_w,
    int pad_d, int pad_h, int pad_w,
    int outpad_d, int outpad_h, int outpad_w,
    int groups
) {
    input = input.contiguous();
    weight = weight.contiguous();

    const int N = input.size(0);
    const int C_in = input.size(1);
    const int D_in = input.size(2);
    const int H_in = input.size(3);
    const int W_in = input.size(4);

    const int C_out_per_group = weight.size(1);
    const int C_out = C_out_per_group * groups;
    const int kD = weight.size(2);
    const int kH = weight.size(3);
    const int kW = weight.size(4);
    const int C_in_per_group = C_in / groups;

    const int D_out = (D_in - 1) * stride_d - 2 * pad_d + kD + outpad_d;
    const int H_out = (H_in - 1) * stride_h - 2 * pad_h + kH + outpad_h;
    const int W_out = (W_in - 1) * stride_w - 2 * pad_w + kW + outpad_w;

    auto output = torch::zeros({N, C_out, D_out, H_out, W_out}, input.options());

    bool has_bias = bias.defined() && bias.numel() > 0;

    const long total = (long)N * C_out * D_out * H_out * W_out;
    const int threads = 256;
    const int blocks = (int)std::min((long)65535 * 256, (total + threads - 1) / threads);

    conv_transpose3d_kernel<<<blocks, threads>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        has_bias ? bias.data_ptr<float>() : nullptr,
        output.data_ptr<float>(),
        N, C_in, D_in, H_in, W_in,
        C_out, D_out, H_out, W_out,
        kD, kH, kW,
        stride_d, stride_h, stride_w,
        pad_d, pad_h, pad_w,
        groups,
        C_in_per_group,
        C_out_per_group,
        has_bias
    );

    return output;
}
"""

conv_transpose3d_cpp_source = r"""
torch::Tensor conv_transpose3d_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride_d, int stride_h, int stride_w,
    int pad_d, int pad_h, int pad_w,
    int outpad_d, int outpad_h, int outpad_w,
    int groups
);
"""

conv_transpose3d_module = load_inline(
    name="conv_transpose3d_module",
    cpp_sources=conv_transpose3d_cpp_source,
    cuda_sources=conv_transpose3d_source,
    functions=["conv_transpose3d_cuda"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Performs a transposed 3D convolution operation with asymmetric input and kernel sizes,
    using a custom CUDA kernel.
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: tuple, stride: tuple = (1, 1, 1), padding: tuple = (0, 0, 0), output_padding: tuple = (0, 0, 0), groups: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.output_padding = output_padding
        self.groups = groups
        self.has_bias = bias

        # Weight layout matching nn.ConvTranspose3d: (in_channels, out_channels/groups, kD, kH, kW)
        self.weight = nn.Parameter(torch.empty(in_channels, out_channels // groups, *kernel_size))
        if bias:
            self.bias = nn.Parameter(torch.empty(out_channels))
        else:
            self.register_parameter('bias', None)

        self.reset_parameters()

    def reset_parameters(self):
        nn.init.kaiming_uniform_(self.weight, a=5 ** 0.5)
        if self.bias is not None:
            fan_in = self.in_channels // self.groups
            for k in self.kernel_size:
                fan_in *= k
            bound = 1 / (fan_in ** 0.5) if fan_in > 0 else 0
            nn.init.uniform_(self.bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        x = x.contiguous().cuda()
        weight = self.weight.contiguous().cuda()
        bias = self.bias.cuda() if self.bias is not None else torch.tensor([], device=x.device, dtype=x.dtype)

        return conv_transpose3d_module.conv_transpose3d_cuda(
            x, weight, bias,
            self.stride[0], self.stride[1], self.stride[2],
            self.padding[0], self.padding[1], self.padding[2],
            self.output_padding[0], self.output_padding[1], self.output_padding[2],
            self.groups
        )


batch_size = 16
in_channels = 32
out_channels = 16
kernel_size = (3, 5, 7)
depth_in = 16
height_in = 32
width_in = 64

def get_inputs():
    x = torch.rand(batch_size, in_channels, depth_in, height_in, width_in)
    return [x]

def get_init_inputs():
    return [in_channels, out_channels, kernel_size]

